def insert_after(doc: Document, marker: str, paragraphs: list[str]) -> None:
    for idx, p in enumerate(doc.paragraphs):
        if p.text.strip() == marker:
            insert_index = idx + 1
            break
    else:
        return

    for text in paragraphs:
        doc.paragraphs[insert_index - 1].insert_paragraph_before(text)
        insert_index += 1


def insert_before(doc: Document, marker: str, paragraphs: list[str]) -> None:
    for idx, p in enumerate(doc.paragraphs):
        if p.text.strip() == marker:
            insert_index = idx
            break
    else:
        return

    for text in paragraphs:
        doc.paragraphs[insert_index].insert_paragraph_before(text)
        insert_index += 1


